:root {
  --ink: #25213a;
  --muted: #756f88;
  --card: #fffdf8;
  --plum: #49356b;
  --lilac: #eee7fa;
  --peach: #f7d6bd;
  --line: #ded6e6;
  --paper: #f8f0e5;
}

* {
  box-sizing: border-box;
}

.listening-card {
  width: 480px;
  overflow: hidden;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--lilac);
}

.eyebrow {
  color: var(--plum);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.date-pill {
  padding: 5px 9px;
  color: var(--plum);
  background: var(--peach);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.card-content {
  padding: 16px;
}

.session-title {
  margin: 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1.15;
}

.session-copy {
  margin: 5px 0 14px;
  color: var(--muted);
  font-size: 14px;
}

.details-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.detail {
  margin: 0;
  padding-left: 9px;
  border-left: 3px solid var(--peach);
  color: var(--ink);
  font-size: 14px;
  line-height: 1.35;
}

.detail-label {
  display: block;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.host {
  display: flex;
  align-items: center;
  gap: 8px;
}

.avatar {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  color: var(--card);
  background: var(--plum);
  border-radius: 50%;
  font-size: 13px;
  font-weight: 800;
}

.host-name,
.host-role {
  display: block;
}

.host-name {
  color: var(--ink);
  font-size: 13px;
}

.host-role {
  color: var(--muted);
  font-size: 11px;
}

.reserve-button {
  padding: 8px 12px;
  color: var(--card);
  background: var(--plum);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}
